import yaml, sys
from collections import defaultdict

d = yaml.safe_load(open(sys.argv[1]))
print(list(d.keys()))
cols = {c['collection']: c for c in d.get('collections', [])}
fields = defaultdict(list)
for f in d.get('fields', []):
    sp = f.get('schema') or {}
    m = f.get('meta') or {}
    extra = []
    if m.get('interface'):
        extra.append(m['interface'])
    if sp.get('foreign_key_table'):
        extra.append('->' + sp['foreign_key_table'])
    if sp.get('is_unique'):
        extra.append('unique')
    if m.get('note'):
        extra.append('# ' + m['note'][:90])
    fields[f['collection']].append(f"{f['field']}: {f.get('type')} {' '.join(extra)}")
for c in sorted(cols):
    meta = cols[c].get('meta') or {}
    print(f"\n## {c}   note: {meta.get('note')}")
    for x in fields[c]:
        print("   ", x)
print("\n## relations")
for r in d.get('relations', []):
    print("  ", r.get('collection'), r.get('field'), '->', r.get('related_collection'), (r.get('meta') or {}).get('one_field'))

